input.command:
cat > /tmp/jqwork/batch.sh <<'SH'
#!/bin/bash
# each line of $1 is a full template
cd /workspace
while IFS= read -r line; do
  [ -z "$line" ] && continue
  ./executable -i "$line" >/tmp/jqwork/o 2>/tmp/jqwork/e
  rc=$?
  printf '### %s\n' "$line"
  printf 'OUT<'; cat /tmp/jqwork/o; printf '> rc=%s\n' "$rc"
  if [ -s /tmp/jqwork/e ]; then printf 'ERR '; cat /tmp/jqwork/e; fi
done < "$1"
SH
chmod +x /tmp/jqwork/batch.sh
cat > /tmp/jqwork/b1.txt <<'EOF'
{{ jq ".a" (dict "a" 1 "b" 2) }}
{{ jq ".a.b" (dict "a" (dict "b" 42)) }}
{{ jq `.["a"]` (dict "a" 1) }}
{{ jq `.a?` 5 }}
{{ jq ".a" 5 }}
{{ jq ".a" (coll.Slice 1 2) }}
{{ jq ".a" nil }}
{{ jq ".[0]" (coll.Slice 1 2 3) }}
{{ jq ".[-1]" (coll.Slice 1 2 3) }}
{{ jq ".[5]" (coll.Slice 1 2 3) }}
{{ jq ".[1:3]" (coll.Slice 1 2 3 4 5) }}
{{ jq ".[:2]" (coll.Slice 1 2 3 4 5) }}
{{ jq ".[2:]" (coll.Slice 1 2 3 4 5) }}
{{ jq ".[-2:]" (coll.Slice 1 2 3 4 5) }}
{{ jq ".[1:3]" "abcdef" }}
{{ jq ".[]" (dict "a" 1 "b" 2) }}
{{ jq ".[]?" 5 }}
{{ jq "..|numbers" (dict "a" 1 "b" (dict "c" 2)) }}
{{ jq "[..]" (dict "a" 1) }}
EOF
/tmp/jqwork/batch.sh /tmp/jqwork/b1.txt

